export default async (): Promise<RequestMessage> => (
{
  // Generators are globals: `requestId` and `stamp` are this collection's
  // scripts, pulled in only because they are called here.
  message: `${requestId("echo")} at ${stamp()}`,
  count: 1,
}
)

draftMetadataScript:
export default async (): Promise<Metadata> => (
{
  // Metadata is the same language as the body, evaluated to
  // { [key: string]: string[] }. Spread the folder chain, then add our own.
  ...gv.metadata.inherit(),
  "x-request-id": [requestId()],
  "x-sent-at": [stamp()],
}
)
